options(bdynets.basemap.auto=FALSE)
library(bdynets)
inside<-function(n)if(exists(n,mode='function'))get(n,mode='function') else getFromNamespace(n,'bdynets')
fail<-function(e)inherits(tryCatch(force(e),error=identity),'error')
r<-data.frame(road_id=c('a','b'));r$geometry<-list(rbind(c(10,50),c(10.01,50)),rbind(c(10.01,50),c(10,50)))
f<-data.frame(road_id=c('a','b','a','b'),time=c(0,0,60,60),flow=c(10,20,12,15))
m<-data.frame(road_id=c('b','a','b','a'),time=c(0,0,60,60),metric='index',value=c(.2,.1,.4,.3))
info<-list(index=list(label='Saved index',unit='index',definition='Source-supplied bounded indicator.',kind='index',scale=list(kind='gradient',stops=c(0,.5,1),palette=c('#00a651','#ffb000','#e02424'))))
saved<-data.frame(time=c(0,60),metric='index',value=c(.151,.351),definition='Saved source mean with original rounding.',label='Saved mean index')
x<-traffic_data(r,f,times=c(0,60),interval_seconds=60,measurements=m,metric_info=info,trends=saved)
v<-inside('.tm_view')(x,metric='index');stopifnot(identical(as.numeric(v$values),c(.1,.3,.2,.4)),v$unit=='index',identical(x$values,matrix(c(10,12,20,15),2)))
stopifnot(identical(traffic_trend(x,metric='index',method='provided')$mean,c(.151,.351)),isTRUE(all.equal(traffic_trend(x,metric='index',method='mean')$mean,c(.15,.35))),fail(traffic_trend(x,method='provided')))
dm<-data.frame(road_id=rep(c('a','b'),2),time=rep(c(0,60),each=2),metric='saved_duration',value=c(5,0,7,2))
di<-list(saved_duration=list(label='Saved condition duration',unit='minutes',definition='Source-provided time under its documented condition.',kind='duration',time_alignment='interval_end',scale=list(kind='classes',breaks=c(5,10),palette=c('#fdd349','#f46d43','#b2182b'),labels=c('0-5','5-10','>10'),right=TRUE)))
y<-traffic_data(r,f,times=c(0,60),interval_seconds=60,measurements=dm,metric_info=di)
d<-inside('.tm_view')(y,'duration');stopifnot(identical(d$values,matrix(c(5,7,0,2),2)),d$measurement$origin=='provided',d$unit=='minutes')
stopifnot(fail(inside('.tm_view')(x,'duration',threshold=10)),fail(inside('.tm_view')(y,'duration',threshold=10)))
rule<-list(definition='Toy interval values meeting an explicit threshold.',interval_meaning='Each value represents its supplied interval.',unit='seconds',missing_policy='break',scale=di$saved_duration$scale)
d<-inside('.tm_view')(x,'duration',threshold=10,comparison='>=',duration_rule=rule);stopifnot(identical(as.numeric(d$values),c(60,120,60,120)),d$unit=='seconds')
c<-inside('.tm_view')(x,'change');stopifnot(identical(inside('.tm_colors')(c(-1,0,1,NA),c$scale),c('#2166ac','#f7f7f7','#b2182b','#94a3b8')))
out<-tempfile();dir.create(out)
traffic_report(x,file.path(out,'index.html'),metric='index',trend_method='provided')
traffic_map(x,file.path(out,'index-map.html'),metric='index',trend_method='provided')
traffic_export(y,file.path(out,'duration'),mode='duration',index=2)
s<-readRDS(file.path(out,'duration','selected-frame.rds'));stopifnot(s$measurement$origin=='provided',s$metric=='saved_duration',identical(s$flow$flow,c(7,2)))
unlink(out,recursive=TRUE);cat('Source metrics, supplied trends, provided durations, explicit rules, source colors and original primary measurements passed.\n')
# Definitions, missing regional series, missing scales and clocks remain explicit.
r$region<-c('West','East')
z<-traffic_data(r,f,times=c(0,60),interval_seconds=60,measurements=m,metric_info=info,trends=saved)
stopifnot(fail(traffic_trend(z,region='West',metric='index',method='provided')))
without_scale<-info;without_scale$index$scale<-NULL
z<-traffic_data(r,f,times=c(0,60),interval_seconds=60,measurements=m,metric_info=without_scale)
stopifnot(traffic_summary(z,metric='index')$available==2,fail(traffic_map(z,tempfile(),metric='index')))
double<-rbind(dm,transform(dm,metric='second_duration'));two<-c(di,list(second_duration=di$saved_duration))
z<-traffic_data(r,f,times=c(0,60),interval_seconds=60,measurements=double,metric_info=two)
stopifnot(fail(inside('.tm_view')(z,'duration')),identical(inside('.tm_view')(z,'duration',metric='second_duration')$values,matrix(c(5,7,0,2),2)))
time0<-as.POSIXct('2026-01-01 00:00:00',tz='UTC')
af<-f;af$time<-time0+f$time;am<-m;am$time<-time0+m$time
z<-traffic_data(r,af,times=time0+c(0,60),interval_seconds=60,measurements=am,metric_info=info)
stopifnot(z$clock=='absolute',identical(z$metrics$index,matrix(c(.1,.3,.2,.4),2)),fail(traffic_data(r,af,times=time0+c(0,60),measurements=m,metric_info=info)))
# Additional metric selection never alters the original measurements or geometry.
original<-serialize(z,NULL);invisible(inside('.tm_view')(z,'change',metric='index'));stopifnot(identical(original,serialize(z,NULL)))
cat('Explicit metadata, unavailable scales/scopes, ambiguous durations, absolute clocks and source immutability passed.\n')
stopifnot(fail(inside('.tm_view')(y,'duration',metric='saved_duration',threshold=1,comparison='>=',duration_rule=rule)),
  fail(inside('.tm_view')(y,'duration',threshold=1,comparison='>=',duration_rule=rule)))
computed_flow<-inside('.tm_view')(y,'duration',metric='flow',threshold=10,comparison='>=',duration_rule=rule)
stopifnot(computed_flow$measurement$origin=='computed',identical(as.numeric(computed_flow$values),c(60,120,60,120)))
